import test from 'node:test';
import assert from 'node:assert/strict';
import { createSeed } from '../seed.js';
import { createPatient, createVisit, signVisit, amendVisit, createDocument, createDocumentRequest, getOwnerHistory, createCareRecord } from '../domain.js';

const vet={id:'user-demo-vet',role:'veterinarian',status:'active',clinicId:'clinic-demo-001'};
const ownerActor={id:'owner:owner-demo-anna',role:'owner',ownerId:'owner-demo-anna'};
test('patient creation links a demo owner and rejects duplicate microchips',()=>{const s=createSeed();const p=createPatient(s,{name:'Burek',species:'Pies',ownerName:'Nowy Opiekun',microchip:'616000000000009'},vet);assert.equal(s.petOwners.find(r=>r.petId===p.id).status,'verified_demo');assert.throws(()=>createPatient(s,{name:'Inny',species:'Kot',ownerName:'Ktoś',microchip:'616000000000009'},vet),/już zapisany/)});
test('visits are drafts until an active vet signs them; signed note is immutable',()=>{const s=createSeed();const v=createVisit(s,{petId:'pet-demo-rex',type:'Badanie',eventAt:'2026-10-15',notes:'Pierwotna treść'},vet);assert.equal(v.status,'draft');assert.throws(()=>signVisit(s,v.id,{...vet,role:'receptionist'}),/wymaga aktywnego/);signVisit(s,v.id,vet);assert.equal(v.status,'signed');assert.equal(v.notes,'Pierwotna treść');assert.throws(()=>signVisit(s,v.id,vet),/nie jest szkicem/)});
test('amendment appends reason and text without overwriting signed source',()=>{const s=createSeed();const v=s.visits[0];const source=v.notes;const amendment=amendVisit(s,v.id,{reason:'Doprecyzowanie wyniku badania',notes:'Dopisano szczegół.'},vet);assert.equal(v.notes,source);assert.equal(v.amendments[0].id,amendment.id);assert.equal(v.amendments[0].reason,'Doprecyzowanie wyniku badania')});
test('owner history excludes hidden, unsigned and unverified records',()=>{const s=createSeed();const h=getOwnerHistory(s,'owner-demo-anna');assert.ok(h.visits.every(v=>v.status==='signed'&&v.ownerVisible));assert.ok(h.documents.every(d=>d.ownerVisible&&d.verification==='verified_demo'));assert.ok(!h.documents.some(d=>d.id==='doc-demo-3'));assert.ok(!h.visits.some(v=>v.id==='visit-demo-3'))});
test('owner document request is stored for manual review and does not share records',()=>{const s=createSeed();const before=getOwnerHistory(s,'owner-demo-anna').documents.length;const r=createDocumentRequest(s,{petId:'pet-demo-rex',scope:'Pełna historia'},ownerActor);assert.equal(r.status,'submitted_demo');assert.equal(getOwnerHistory(s,'owner-demo-anna').documents.length,before);assert.throws(()=>createDocumentRequest(s,{petId:'pet-demo-figa',scope:'Dokumenty'},ownerActor),/Brak zweryfikowanego/)});
test('owner supplied and AI extracted documents remain unverified and hidden',()=>{const s=createSeed();const a=createDocument(s,{petId:'pet-demo-rex',title:'Zdjęcie',kind:'Załącznik',source:'owner_supplied',ownerVisible:true},vet);const b=createDocument(s,{petId:'pet-demo-rex',title:'OCR',kind:'Notatka',source:'ai_extracted_unverified',ownerVisible:true},vet);assert.equal(a.verification,'unverified');assert.equal(a.ownerVisible,true);assert.equal(b.verification,'unverified');assert.equal(b.ownerVisible,false);assert.ok(!getOwnerHistory(s,'owner-demo-anna').documents.includes(a))});
test('vaccine next date cannot precede event date',()=>{const s=createSeed();assert.throws(()=>createCareRecord(s,'vaccinations',{petId:'pet-demo-rex',title:'Szczepienie',eventAt:'2026-10-12',nextDate:'2026-10-01'},vet),/nie może poprzedzać/)});
